project.scriptdef:


project.log("--- Read Require-Extension from "+attributes.get( "file" )+" ---");
var filename = attributes.get( "file" );
var manifest = new java.util.jar.Manifest( new java.io.FileInputStream( new java.io.File( filename ) ) );
var attrs = manifest.getMainAttributes();
var str = attrs.getValue( "Require-Extension" );
project.log("--- RAW ---");
project.log(str);
project.log("------");
var arr = str.split( "," );
var count = 0;
var ids = "";
var data = "";
var versions = "";
var labels = "";
for (var i = 0 ; i < arr.length ; i++ ) {
	var line = arr[ i ];
	project.log("- "+line);
	var extArr = line.split( ';' );

	if ( extArr.length < 1 ) 
		continue;
	count++;
	// the first is the id
	if ( ids.length >0 )
		ids += ",";
	ids += extArr[ 0 ];
	if ( data.length > 0 )
		data+=",";
	var strGAV = extArr[ 0 ];
	var _id = extArr[ 0 ];

	project.setProperty( "reqExt.ID" + ( i + 1 ), _id );

	// the rest has names
	var _version="";
	var _name="";
	var group="";
	var groupPath="";
	var artifact="";

	// GAV
	var gav = strGAV.split( ':' );
	if ( gav.length > 2 ) {
		_name=gav[1].trim();
		group=gav[0].trim();
		groupPath=group.replace('.','/');
		artifact=gav[1].trim();
		_id = group+"_"+artifact;
		var names=_name.split( '-' );
		if(names.length>1) {
			var tmp="";
			for(var x=0;x<names.length;x++) {
				tmp+=names[x][0].toUpperCase()+names[x].substring(1);
			}
			_name=tmp;
		}

		_version=gav[2].trim();
	}
	//data += _id+"-"+_version;
	data += "mvn_" + group + "_" + artifact + "_" + _version;

	if(extArr.length>1) {
		for (var y = 1; y < extArr.length ; y++ ) {
			var ext = extArr[ y ];
			var index = ext.indexOf( '=' );
			if ( index == -1 ) 
				continue;
			var name = ext.substring( 0, index ).trim();
			var value = ext.substring( index + 1 ).trim();
			if ( name == "version" ) {
				if ( versions.length > 0)
					versions += ",";
				versions += value;
				data += ";" + value;
				_version = value;
			}
			if ( name == "label" ) {
				if( labels.length > 0)
					labels += ",";
				labels += value;
			} else if ( name == "name" ) {
				_name = value;
			}
			project.setProperty( "reqExt." + name + ( i + 1 ), value );
		}
	}


	project.log("ext" + _name + " = "+ _version);
	project.log(_id);

	project.setProperty( "reqExt." + _name, _version );
	project.setProperty( "ext" + _name + "Version", _version );
	project.setProperty( "ext" + _name + "Artifact", artifact );
	project.setProperty( "ext" + _name + "Group", group );
	project.setProperty( "ext" + _name + "GroupPath", groupPath );
	project.setProperty( "ext" + _name, _id );
	project.setProperty( "ext" + _name + "Filename", "mvn_" + group + "_" + artifact + "_" + _version + ".lex");
}
project.setProperty( "reqExt.length", count + "" );
project.setProperty( "reqExt.ids", ids );
project.setProperty( "reqExt.versions", versions );
project.setProperty( "reqExt.labels", labels );
project.setProperty( "reqExt.data", data );

//








var group    = attributes.get("group").trim();
var artifact = attributes.get("artifact").trim();
var version  = attributes.get("version").trim();

// remove surrounding quotes if present
if (version.startsWith('"') && version.endsWith('"'))
    version = version.substring(1, version.length() - 1).trim();

project.setProperty(
    attributes.get("property"),
    "mvn_" + group + "_" + artifact + "_" + version + ".lex"
);






function normalizeUrl(base) {
	return base.endsWith("/") ? base : base + "/";
}

function isSnapshot(version) {
	return version.toUpperCase().indexOf("SNAPSHOT") !== -1;
}

function groupPath(group) {
	return group.replace(/\./g, "/");
}

function literalLexUrl(repoUrl, group, artifact, version) {
	var g = groupPath(group);
	return normalizeUrl(repoUrl) + g + "/" + artifact + "/" + version + "/" + artifact + "-" + version + ".lex";
}

function resolvedLexUrl(repoUrl, group, artifact, version, resolvedValue) {
	var g = groupPath(group);
	return normalizeUrl(repoUrl) + g + "/" + artifact + "/" + version + "/" + artifact + "-" + resolvedValue + ".lex";
}

function httpStatus(url) {
	var conn = new java.net.URL(String(url)).openConnection();
	conn.setRequestMethod("HEAD");
	conn.setConnectTimeout(10000);
	conn.setReadTimeout(60000);
	conn.setInstanceFollowRedirects(true);
	try {
		conn.connect();
		return conn.getResponseCode();
	} catch (e) {
		return -1;
	}
}

function fetchText(url) {
	var conn = new java.net.URL(String(url)).openConnection();
	conn.setConnectTimeout(10000);
	conn.setReadTimeout(60000);
	conn.setInstanceFollowRedirects(true);
	var is = conn.getInputStream();
	var reader = new java.io.BufferedReader(new java.io.InputStreamReader(is, "UTF-8"));
	var sb = new java.lang.StringBuilder();
	var line;
	while ((line = reader.readLine()) != null) {
		sb.append(line);
	}
	reader.close();
	return sb.toString();
}

function childText(node, name) {
	var children = node.getChildNodes();
	for (var i = 0; i < children.getLength(); i++) {
		var child = children.item(i);
		if (child.getNodeName() === name) {
			return child.getTextContent().trim();
		}
	}
	return null;
}

function resolveSnapshotLexValue(repoUrl, group, artifact, version) {
	var g = groupPath(group);
	var metaUrl = normalizeUrl(repoUrl) + g + "/" + artifact + "/" + version + "/maven-metadata.xml";
	try {
		var xml = fetchText(metaUrl);
		var factory = javax.xml.parsers.DocumentBuilderFactory.newInstance();
		factory.setNamespaceAware(false);
		var doc = factory.newDocumentBuilder().parse(new org.xml.sax.InputSource(new java.io.StringReader(xml)));
		var nodes = doc.getElementsByTagName("snapshotVersion");
		var fallback = null;
		for (var i = 0; i < nodes.getLength(); i++) {
			var node = nodes.item(i);
			var ext = childText(node, "extension");
			var classifier = childText(node, "classifier");
			var value = childText(node, "value");
			if (ext === "lex" && value) {
				if (!classifier) {
					return value;
				}
				if (fallback === null) {
					fallback = value;
				}
			}
		}
		return fallback;
	} catch (e) {
		return null;
	}
}

function tryDownload(url, dest, tried) {
	var urlStr = String(url);
	tried.push(urlStr);
	var status = httpStatus(urlStr);
	if (status >= 200 && status < 300) {
		project.log("Downloading extension from " + urlStr);
		var get = project.createTask("get");
		get.setSrc(new java.net.URL(urlStr));
		get.setDest(new java.io.File(dest));
		get.perform();
		return true;
	}
	project.log("Extension not found (" + status + "): " + urlStr);
	return false;
}

var group = attributes.get("group").trim();
var artifact = attributes.get("artifact").trim();
var version = attributes.get("version").trim();
var dest = attributes.get("dest").trim();

if (version.startsWith('"') && version.endsWith('"')) {
	version = version.substring(1, version.length() - 1).trim();
}

var repos = [];
if (isSnapshot(version)) {
	// CDN is excluded for SNAPSHOTs: it caches the literal URL and serves stale builds
	// when a snapshot is republished. Always resolve via maven-metadata.xml instead.
	repos.push(project.getProperty("extURLSnapshot"));
	repos.push(project.getProperty("extURLMaven"));
} else {
	repos.push(project.getProperty("extURLMaven"));
	repos.push(project.getProperty("extURLCDN"));
}

var tried = [];
var downloaded = false;
for (var r = 0; r < repos.length && !downloaded; r++) {
	var repoUrl = repos[r];
	if (!repoUrl) {
		continue;
	}

	if (isSnapshot(version)) {
		// for SNAPSHOTs always use metadata resolution to get the latest timestamped build
		var resolved = resolveSnapshotLexValue(repoUrl, group, artifact, version);
		if (resolved) {
			downloaded = tryDownload(resolvedLexUrl(repoUrl, group, artifact, version, resolved), dest, tried);
		}
	} else {
		if (tryDownload(literalLexUrl(repoUrl, group, artifact, version), dest, tried)) {
			downloaded = true;
		}
	}
}

if (!downloaded) {
	throw new java.lang.RuntimeException(
		"Could not download [" + group + ":" + artifact + ":" + version + ".lex] from any repository. Tried:\n- "
		+ tried.join("\n- ")
	);
}






var sourceDir = attributes.get( "source" );
var targetDir = attributes.get( "target" );
var extensions = attributes.get( "extensions" ).split(",");
if (extensions.length == 0 )
	throw ( "copyExtensions: no extensions specified?" );

var copy = project.createTask( "copy" );
var echo = project.createTask( "echo" );

echo.setMessage( "copying Extensions to : " + targetDir );
echo.perform();	

// --- Debug: List files in source directory ---
var sourceFolder = new java.io.File(sourceDir);
var files = sourceFolder.list();
if (files != null) {
    project.log("--- Listing Source Directory: " + sourceDir + " ---");
    for (var i = 0; i < files.length; i++) {
        project.log("File found in cache: " + files[i]);
    }
    project.log("---------------------------------------------------");
} else {
    project.log("--- Source Directory is Empty or Invalid: " + sourceDir + " ---");
}



for (var e in extensions){
	var extFile = extensions[e].split(";").join("-") + ".lex";
	echo.setMessage( "copy Extension: " + sourceDir + "/" + extFile );
	echo.perform();	
	copy.setFile( new java.io.File( sourceDir + "/" + extFile ) );
	copy.setTofile( new java.io.File( targetDir + "/" + extFile ) );
	copy.perform();
}
